    pub fn find_file(&self, path: &str) -> Option<&FileEntry> {
        let mut cleaned_path = path.to_string();
        while cleaned_path.starts_with("./") || cleaned_path.starts_with("/.") {
            cleaned_path.drain(..2);
        }
        while cleaned_path.starts_with("./") || cleaned_path.starts_with("/") {
            cleaned_path.drain(..1);
        }
        self.files.iter().find(|f| f.path == cleaned_path)
    }
